qk(){ local f="$GE/kubin.txt" i=2; tva f a '--' '\r=\&\a(`n)'; [ "$1" = ui ]&&{ shift;SE(){ swaymsg exec "$*";};i=1;}; f8 "qk${1:+.$1}" <<< "${a[$i]}"; unset a; }
is(){ case $# in 1) [ -n "${!1}" ];; 2) [[ "$1" == $2 ]];; *) return 1;; esac; }
relp(){ local r="${1#.}" d="$PWD" n f s segs i;[[ "$r" == */* ]]&&{ n="${r##*/}";f="${r%/*}";}||{ n="$r";f="";};IFS=/ read -ra segs<<<"$f";for s in "${segs[@]}";do [ -z "$s" ]&&continue;if [ -z "${s//-/}" ];then for((i=0;i<${#s};i++));do d=${d%/*};d=${d:-/};done;else d="$d/$s";fi;done;if [ -z "$n" ];then [ -d "$d" ]&&echo "$d"||return 1;elif [[ "$n" == *.* || -f "$d/$n" ]];then [ -f "$d/$n" ]&&echo "$d/$n"||return 1;else local m;for m in "$d/$n".*;do [ -f "$m" ]&&{ echo "$m";return 0;};done;return 1;fi;}
f6(){ local q="$1" l s pat m a; l=$(</dev/stdin); case "$q" in *~) pat="${q%\~}"; tva l m "$pat"; if [ -n "$m" ]; then mapfile -t a <<< "${m%$'\n'}"; [ ${#a[@]} -eq 1 ]&&printf '%s\n' "${a[0]}"||fzf -m --query="$pat"<<<"$m"; else fzf -m <<<"$l"; fi;; *\?) pat="${q%\?}"; fzf -m --query="$pat"<<<"$l";; */) tva ".fzf --filter=${q%/}" . '1.^' '\&\n' <<<"$l";; *) return 1;; esac; }
f8(){ local n="${1%%.*}" k="${1#*.}" p e s t f="$UT/f8.txt"; [ "$k" = "$1" ]&&k=""; [ -t 0 ]&&p="$KT/f8/$n.txt"||p=/dev/stdin; tva f e "1.^${n}[*][*]"; e="${e#*[*][*]}"; if [ -n "$k" ]&&[[ "$k" == *[~?/] ]]; then cf0 s eval "$e" <"$p" -- f6 "$k"; elif [ -n "$k" ]; then cf0 t eval "$e" <"$p"; tva t s "1.^$k"$'\t'; else cf0 s eval "$e" <"$p" -- fzf --delimiter=$'\t' --with-nth=1 --select-1; fi; [ -n "$s" ]&&s="${s#*$'\t'}"; eval "$s" <&1 ; }
